#pragma once
int runPhoneRemoteRetentionChecks(){juce::ScopedJuceInitialiser_GUI gui;auto require=[](bool ok,const char* text){if(!ok)throw std::runtime_error(text);};try{
 RackProcessor rack;auto finish=[&]{for(int i=0;i<1500&&rack.phoneWork.getNumJobs()>0;++i)juce::Thread::sleep(2);require(rack.phoneWork.getNumJobs()==0,"favourite worker completes");};auto& p=*rack.loops[0];p.autoSave=false;auto root=LibraryStore::root();root.createDirectory();
 // Low-sorting current hashes were immediately discarded once 256 older files existed.
 auto file=root.getChildFile("Current.wav");for(int i=0;!RackProcessor::phoneKey(file.getFullPathName()).startsWithChar('0');++i)file=root.getChildFile("Current"+juce::String(i)+".wav");auto data=std::make_shared<AudioData>();data->path=file.getFullPathName();data->buffer.setSize(1,1);data->buffer.clear();p.audio=data;
 for(int i=0;i<256;++i){auto key="f"+juce::String(i).paddedLeft('0',8);rack.phoneRecent[key]=root.getChildFile(juce::String(i)+".wav");rack.phoneLastSeen[key]=++rack.phoneSeenSerial;}
 auto rows=rack.phoneRows(1);require(rows.size()==1,"current file is displayed");auto key=rows[0]["key"].toString();require(rack.phoneRecent.count(key)&&rack.phoneRecent.size()==256,"current file survives full recent-file cache");rack.phoneAction(0,"fav",key);finish();require(LibraryStore::read("favourites.json").hasProperty(file.getFullPathName()),"favourite works after more than 256 files");
 // The tap still applies to the displayed file after playback moves on.
 auto next=std::make_shared<AudioData>();next->path=root.getChildFile("Next.wav").getFullPathName();next->buffer.setSize(1,1);p.audio=next;rack.phoneRows(1);LibraryStore::setFavourite(file,{});rack.phoneAction(0,"fav",key);finish();require(LibraryStore::read("favourites.json").hasProperty(file.getFullPathName()),"transition does not redirect the favourite");
 data->embedded526=true;data->path=root.getChildFile("Recovered/Original.wav").getFullPathName();data->librarySourcePath517=root.getChildFile("Library/Original.wav").getFullPathName();p.audio=data;rows=rack.phoneRows(1);rack.phoneAction(0,"fav",rows[0]["key"].toString());finish();auto favourites=LibraryStore::read("favourites.json");require(favourites.hasProperty(data->librarySourcePath517)&&!favourites.hasProperty(data->path),"embedded playback favourites the original library file");require((bool)rack.phoneRows(1)[0]["favourite"],"phone displays original-file favourite status");
 rack.phoneAction(0,"fav","expired");require(rack.phoneRows(1)[0]["error"].toString().isNotEmpty(),"unknown file reports an error instead of success");
 std::cout<<"Phone remote: full cache retention, exact displayed file across transitions, embedded original-file favourites and error feedback passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<"Phone remote failed: "<<e.what()<<"\n";return 1;}}
